      * so k steps equal one k·delta_fy jump. */
     int64_t col_min = (int64_t) x_org;
-    int64_t col_max = (int64_t) x_org + (int64_t) width - 1;
+    int64_t col_max = (int64_t) x_org + (int64_t) width;

     if (unlikely (cx1 < col_min))
     {
