       return; /* Entirely right of the surface. */

     int32_t x_b = (int32_t) hb_clamp (((int64_t) cx0 + 1) * HB_RASTER_ONE_PIXEL,
@@ -1382,7 +1382,7 @@ edge_sweep_row (int32_t                *area,
